DapConfig? _dapFrom(Object? raw) {
  if (raw is! Map) {
    print('[dap] config: faDap absent/not a map — hub presence off');
    return null;
  }
  final url = '${raw['url'] ?? ''}'.trim();
  if (url.isEmpty) {
    print('[dap] config: empty url — hub presence off');
    return null;
  }
  final name = '${raw['name'] ?? ''}'.trim();
